import { z } from "zod";
export const OrderSchema = z.object({
  id: z.string().uuid(),
  customerId: z.string().min(1, "customer required"),
  items: z.array(OrderItemSchema).nonempty("empty cart"),
});
export type Order = z.infer<typeof OrderSchema>;   // one artifact: type + runtime guard
export function createOrder(raw: unknown): Order {
  const result = OrderSchema.safeParse(raw);
  if (!result.success) throw new DomainError(result.error.message);
  return result.data;
}
